            ((Chunk0C03000A)clone).U22Ref = context.Clone(this.U22Ref)!;
        }

        public override void ReadWrite(CVisPostFx_ToneMapping n, GbxReaderWriter rw)
        {
            rw.VersionInt32(this);
            rw.NodeRef(ref U01Ref);
            rw.NodeRef(ref U02Ref);
            rw.NodeRef(ref U03Ref);
            rw.NodeRef(ref U04Ref);
            rw.NodeRef(ref U05Ref);
            rw.NodeRef(ref U06Ref);
            rw.NodeRef(ref U07Ref);
            rw.NodeRef(ref U08Ref);
            rw.NodeRef(ref U09Ref);
            rw.NodeRef(ref U10Ref);
            rw.NodeRef(ref U11Ref);
            rw.NodeRef(ref U12Ref);
            rw.NodeRef(ref U13Ref);
            rw.NodeRef(ref U14Ref);
            rw.NodeRef(ref U15Ref);
            rw.NodeRef(ref U16Ref);
            rw.NodeRef(ref U17Ref);
            rw.NodeRef(ref U18Ref);
            rw.NodeRef(ref U19Ref);
            rw.NodeRef(ref U20Ref);
            rw.NodeRef(ref U21Ref);

            if (Version == 1)
            {
                rw.NodeRef(ref U22Ref);
            }
        }
    }

    internal override IChunk? NewChunk(uint chunkId) => chunkId switch
    {
        0x0C030000 => new Chunk0C030000(),
        0x0C030001 => new Chunk0C030001(),
        0x0C030002 => new Chunk0C030002(),
        0x0C030003 => new Chunk0C030003(),
        0x0C030004 => new Chunk0C030004(),
        0x0C030005 => new Chunk0C030005(),
        0x0C030006 => new Chunk0C030006(),
        0x0C030007 => new Chunk0C030007(),
        0x0C030008 => new Chunk0C030008(),
        0x0C030009 => new Chunk0C030009(),
        0x0C03000A => new Chunk0C03000A(),
        _ => base.NewChunk(chunkId),
    };
}
